(async()=>{const stage=document.getElementById('wine-stage'),metric=document.getElementById('wine-metric'),split=document.getElementById('wine-split'),chart=document.getElementById('wine-chart'),detail=document.getElementById('wine-detail');try{const response=await fetch('assets/wine/results.json');if(!response.ok)throw Error();const data=await response.json();function render(){const key=split.value+' - '+metric.value,rows=Object.entries(data[stage.value]).sort((a,b)=>metric.value==='R-squared'?b[1][key]-a[1][key]:a[1][key]-b[1][key]);const max=Math.max(...rows.map(([,m])=>Math.abs(m[key])),.001);chart.replaceChildren();rows.forEach(([name,values])=>{const b=document.createElement('button');b.type='button';b.className='wine-row'+(values[key]<0?' negative':'');const label=document.createElement('span');label.textContent=name;const track=document.createElement('span');track.className='wine-track';const fill=document.createElement('i');fill.className='wine-fill';fill.style.width=Math.abs(values[key])/max*100+'%';track.append(fill);const value=document.createElement('strong');value.textContent=values[key].toFixed(3);b.append(label,track,value);b.setAttribute('aria-label',name+': '+key+' '+values[key].toFixed(3));const inspect=()=>{detail.textContent=name+' · '+metric.value+' · Training: '+values['train - '+metric.value].toFixed(3)+' · Test: '+values['test - '+metric.value].toFixed(3)+'. '+(metric.value==='R-squared'?'Higher is better; negative values mean worse than the test-mean benchmark on the test sample.':'Lower is better. ')+(stage.value==='initial'&&name==='Gradient Boosting'?'Corrected label: this initial model is sklearn GradientBoostingRegressor. ':'')+'Saved notebook results, not a fresh run.';};b.addEventListener('click',inspect);b.addEventListener('focus',inspect);chart.append(b);});detail.textContent='Models are sorted by '+split.value+' '+metric.value+'. Select a row to inspect the training/test gap. '+(metric.value==='R-squared'?'Bar lengths show absolute magnitude; red and the minus sign identify negative R².':'Bar lengths show error magnitude, not accuracy.');}for(const c of [stage,metric,split])c.addEventListener('change',render);render();}catch{detail.textContent='Saved results could not be loaded. Please reload the page.';}})();
